type Page='auth'|'onboarding'|'today'|'history'|'trends'|'growth'|'family'|'join'|'reset-password';
// `amount` is typed in the display unit (ml or oz); `mode` picks whether the input is volume or nursing minutes.
type Form={baby_id:string;amount:string;duration:string;mode:'vol'|'min';feeding_type:FeedingType;fed_at:string;note:string};
const input='ui-input';
const primary='ui-primary';
const card='ui-card';
type BabyForm={name:string;nickname:string;birthday:string;sex:BabySex|'';gestWeeks:string;gestDays:string};
const emptyBabyForm:BabyForm={name:'',nickname:'',birthday:'',sex:'',gestWeeks:'',gestDays:''};
// Feedings older than this are only fetched when the history calendar navigates to them.
const FEEDING_WINDOW_DAYS=60;
const time=(iso:string)=>new Date(iso).getTime();
const byNewest=(a:Feeding,b:Feeding)=>time(b.fed_at)-time(a.fed_at);
function getError(e:unknown){
 const message=e instanceof Error?e.message:e&&typeof e==='object'&&'message' in e&&typeof e.message==='string'?e.message:tr('操作失败，请检查网络后重试。','Something went wrong. Check your connection and try again.');
 if(message.includes('already linked to a family')||message.includes('family_members_one_family_per_user_idx'))return tr('此账号已经绑定了一个家庭。','This account is already linked to a family.');
 if(message.includes('Family code is invalid'))return tr('家庭编码无效，请向家庭成员确认后重试。','Invalid family code. Check it with your family and try again.');
 if(message.includes('Invite is invalid or expired'))return tr('邀请链接无效或已过期。','This invite link is invalid or has expired.');
 if(message.includes('Cannot coerce the result to a single JSON object'))return tr('这条记录可能已被其他家人删除，请刷新后再试。','This record may have been deleted by someone else. Refresh and try again.');
 return message;
}
function validTime(value:string){const n=new Date(value).getTime();return Number.isFinite(n)&&n<=Date.now()+5*60000&&n>=new Date('2000-01-01').getTime();}
function windowStart(){const d=localDay();d.setDate(d.getDate()-FEEDING_WINDOW_DAYS);return d.toISOString();}
async function fetchFeedings(familyId:string,since:string|null,before:string|null=null){
 const sb=supabase();const all:Feeding[]=[];
 for(let start=0;;start+=1000){
  let query=sb.from('feedings').select('*').eq('family_id',familyId);
  if(since)query=query.gte('fed_at',since);
  if(before)query=query.lt('fed_at',before);
  const {data,error}=await query.order('fed_at',{ascending:false}).order('id').range(start,start+999);
  if(error)throw error;
  all.push(...(data??[]) as Feeding[]);
  if((data??[]).length<1000)break;
 }
 return all;
}

export default function App({page,inviteCode}:{page:Page;inviteCode?:string}){
 const lang=useLang();
 const unit=useUnit();
 const [settingsOpen,setSettingsOpen]=useState(false);
 const router=useRouter(); const [user,setUser]=useState<User|null>(null);const [ready,setReady]=useState(false);
 const [families,setFamilies]=useState<Family[]>([]);const [familyId,setFamilyId]=useState('');const [familiesLoaded,setFamiliesLoaded]=useState(false);const [loadedFamilyId,setLoadedFamilyId]=useState('');const [babies,setBabies]=useState<Baby[]>([]);const [avatarUrls,setAvatarUrls]=useState<Record<string,string>>({});const [feedings,setFeedings]=useState<Feeding[]>([]);const [measurements,setMeasurements]=useState<GrowthMeasurement[]>([]);const [members,setMembers]=useState<Member[]>([]);
 const [busy,setBusy]=useState(false);const [loading,setLoading]=useState(false);const [loadingOlder,setLoadingOlder]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('');
 const [form,setForm]=useState<Form|null>(null);const [editing,setEditing]=useState<string|null>(null);const [deleteId,setDeleteId]=useState<string|null>(null);
 const [avatarDraft,setAvatarDraft]=useState<{baby:Baby;url:string}|null>(null);
 const [pullDistance,setPullDistance]=useState(0);const [refreshing,setRefreshing]=useState(false);const pullStart=useRef<{x:number;y:number}|null>(null);const pullDistanceRef=useRef(0);
 const [range,setRange]=useState<7|30>(7);
 const [now,setNow]=useState(()=>Date.now());
 // Earliest fed_at currently held in `feedings`; null means the full history is loaded.
 const loadedSince=useRef<string|null>(null);
 const [familyName,setFamilyName]=useState('');const [familyCode,setFamilyCode]=useState('');const [babyForm,setBabyForm]=useState<BabyForm>(emptyBabyForm);const [babyEdit,setBabyEdit]=useState<Baby|null>(null);const [babyFormOpen,setBabyFormOpen]=useState(false);
 const activeBabies=useMemo(()=>babies.filter(b=>b.is_active),[babies]);
 const family=families.find(f=>f.id===familyId);
 const showError=(e:unknown)=>{setError(getError(e));setSuccess('');};
 const recorderName=useCallback((userId:string)=>userId===user?.id?tr('我','Me'):members.find(m=>m.user_id===userId)?.display_name||tr('家人','Family'),[user,members]);

 // Local state updates shared by our own saves and by realtime events from other devices.
 const upsertFeeding=useCallback((row:Feeding)=>setFeedings(list=>[...list.filter(f=>f.id!==row.id),row].sort(byNewest)),[]);
 const dropFeeding=useCallback((id:string)=>setFeedings(list=>list.filter(f=>f.id!==id)),[]);
 const upsertGrowth=useCallback((row:GrowthMeasurement)=>setMeasurements(list=>[...list.filter(m=>m.id!==row.id),row].sort((a,b)=>b.measured_at.localeCompare(a.measured_at))),[]);
 const dropGrowth=useCallback((id:string)=>setMeasurements(list=>list.filter(m=>m.id!==id)),[]);

 useEffect(()=>{let live=true;try{const sb=supabase();sb.auth.getUser().then(({data})=>{if(live){setUser(data.user);setReady(true);}}).catch(e=>{if(live){showError(e);setReady(true);}});const {data:{subscription}}=sb.auth.onAuthStateChange((_event,session)=>{if(live){setUser(session?.user??null);setReady(true);}});return()=>{live=false;subscription.unsubscribe();};}catch(e){showError(e);setReady(true);}},[]);
 const loadFamilies=useCallback(async()=>{if(!user)return;const sb=supabase();const {data:links,error:e}=await sb.from('family_members').select('family_id').eq('user_id',user.id);if(e)throw e;const ids=(links??[]).map(x=>x.family_id as string);if(!ids.length){setFamilies([]);setFamilyId('');return;}const {data,error:fe}=await sb.from('families').select('id,name,family_code,created_by').in('id',ids).order('created_at');if(fe)throw fe;const rows=(data??[]) as Family[];setFamilies(rows);setFamilyId(rows[0]?.id??'');},[user]);
 const loadBabies=useCallback(async()=>{if(!familyId)return;const sb=supabase();const {data,error:e}=await sb.from('babies').select('*').eq('family_id',familyId).order('created_at');if(e)throw e;const babyRows=(data??[]) as Baby[];setBabies(babyRows);const paths=babyRows.flatMap(b=>b.avatar_path?[b.avatar_path]:[]);if(paths.length){const {data:signed}=await sb.storage.from('baby-avatars').createSignedUrls(paths,3600);const byPath=new Map((signed??[]).flatMap(item=>item.signedUrl?[[item.path,item.signedUrl] as const]:[]));setAvatarUrls(Object.fromEntries(babyRows.flatMap(b=>b.avatar_path&&byPath.get(b.avatar_path)?[[b.id,byPath.get(b.avatar_path)!]]:[])));}else setAvatarUrls({});},[familyId]);
 const loadMembers=useCallback(async()=>{if(!familyId)return;const sb=supabase();const {data,error:e}=await sb.from('family_members').select('id,user_id,role').eq('family_id',familyId);if(e)throw e;const links=(data??[]) as Member[];const ids=links.map(m=>m.user_id);if(ids.length){const {data:profiles}=await sb.from('profiles').select('id,display_name').in('id',ids);setMembers(links.map(m=>({...m,display_name:profiles?.find(p=>p.id===m.user_id)?.display_name||null})));}else setMembers([]);},[familyId]);
 const loadGrowth=useCallback(async()=>{if(!familyId)return;const {data,error:e}=await supabase().from('growth_measurements').select('*').eq('family_id',familyId).order('measured_at',{ascending:false});if(e)throw e;setMeasurements((data??[]) as GrowthMeasurement[]);},[familyId]);
 // Re-fetch the loaded window (keeps any older months the history page already pulled in).
 const refreshFeedings=useCallback(async()=>{if(!familyId)return;const since=loadedSince.current;const rows=await fetchFeedings(familyId,since);setFeedings(list=>[...(since?list.filter(f=>time(f.fed_at)<time(since)):[]),...rows].sort(byNewest));},[familyId]);
 const loadData=useCallback(async()=>{if(!familyId)return;setLoading(true);try{const since=windowStart();const [rows]=await Promise.all([fetchFeedings(familyId,since),loadBabies(),loadMembers(),loadGrowth()]);loadedSince.current=since;setFeedings(rows);}catch(e){showError(e);}finally{setLoading(false);setLoadedFamilyId(familyId);}},[familyId,loadBabies,loadMembers,loadGrowth]);
 const ensureFeedingsSince=useCallback(async(from:Date)=>{
  const loaded=loadedSince.current;if(!familyId||loaded===null||from.getTime()>=time(loaded))return;
  const since=from.toISOString();setLoadingOlder(true);
  try{const rows=await fetchFeedings(familyId,since,loaded);loadedSince.current=loadedSince.current&&time(loadedSince.current)<time(since)?loadedSince.current:since;setFeedings(list=>{const ids=new Set(list.map(f=>f.id));return [...list,...rows.filter(f=>!ids.has(f.id))].sort(byNewest);});}
  catch(e){showError(e);}finally{setLoadingOlder(false);}
 },[familyId]);
 const refreshVisible=useCallback(async()=>{await Promise.all([refreshFeedings(),loadGrowth()]);},[refreshFeedings,loadGrowth]);

 useEffect(()=>{if(user){setFamiliesLoaded(false);loadFamilies().catch(showError).finally(()=>setFamiliesLoaded(true));}else {setFamilies([]);setFamilyId('');setFamiliesLoaded(false);}},[user,loadFamilies]);
 useEffect(()=>{if(familyId)loadData();else {setBabies([]);setAvatarUrls({});setFeedings([]);setMeasurements([]);setLoadedFamilyId('');}},[familyId,loadData]);

 // Live sync: other family members' changes arrive without pulling to refresh.
 useEffect(()=>{
  if(!familyId)return;
  const sb=supabase();const filter=`family_id=eq.${familyId}`;let joined=false;
  const channel=sb.channel(`family-${familyId}`)
   .on<Feeding>('postgres_changes',{event:'INSERT',schema:'public',table:'feedings',filter},payload=>upsertFeeding(payload.new))
   .on<Feeding>('postgres_changes',{event:'UPDATE',schema:'public',table:'feedings',filter},payload=>upsertFeeding(payload.new))
   // Delete events cannot be filtered and only carry the primary key; unknown ids are a no-op.
   .on<Feeding>('postgres_changes',{event:'DELETE',schema:'public',table:'feedings'},payload=>{if(payload.old.id)dropFeeding(payload.old.id);})
   .on<GrowthMeasurement>('postgres_changes',{event:'INSERT',schema:'public',table:'growth_measurements',filter},payload=>upsertGrowth(payload.new))
   .on<GrowthMeasurement>('postgres_changes',{event:'UPDATE',schema:'public',table:'growth_measurements',filter},payload=>upsertGrowth(payload.new))
   .on<GrowthMeasurement>('postgres_changes',{event:'DELETE',schema:'public',table:'growth_measurements'},payload=>{if(payload.old.id)dropGrowth(payload.old.id);})
   .on('postgres_changes',{event:'*',schema:'public',table:'babies',filter},()=>{loadBabies().catch(()=>{});})
   .on('postgres_changes',{event:'*',schema:'public',table:'family_members',filter},()=>{loadMembers().catch(()=>{});})
   .subscribe(status=>{
    // After a dropped connection (e.g. phone was locked), catch up on anything missed.
    if(status==='SUBSCRIBED'){if(joined)refreshVisible().catch(()=>{});joined=true;}
   });
  return()=>{void sb.removeChannel(channel);};
 },[familyId,upsertFeeding,dropFeeding,upsertGrowth,dropGrowth,loadBabies,loadMembers,refreshVisible]);

 // Keep "time since last feeding" current, and resync when the app returns to the foreground.
 useEffect(()=>{
  const tick=()=>setNow(Date.now());
  const timer=window.setInterval(tick,30000);
  let hiddenAt=0;
  const onVisible=()=>{
   if(document.visibilityState==='hidden'){hiddenAt=Date.now();return;}
   tick();
   if(familyId&&Date.now()-hiddenAt>30000)refreshVisible().catch(()=>{});
  };
  document.addEventListener('visibilitychange',onVisible);window.addEventListener('online',onVisible);
  return()=>{window.clearInterval(timer);document.removeEventListener('visibilitychange',onVisible);window.removeEventListener('online',onVisible);};
 },[familyId,refreshVisible]);

 useEffect(()=>{if(!ready)return;if(!user&&!['auth','reset-password'].includes(page)){if(page==='join'&&inviteCode)localStorage.setItem('pendingInvite',inviteCode);router.replace('/auth');}else if(user&&page==='auth'&&familiesLoaded){const pending=localStorage.getItem('pendingInvite');router.replace(pending?`/join/${pending}`:families.length?'/today':'/onboarding');}else if(user&&page==='onboarding'&&familiesLoaded&&families.length){router.replace('/today');}},[ready,user,page,inviteCode,router,families.length,familiesLoaded]);
 useEffect(()=>{if(user&&page==='join'&&inviteCode)localStorage.removeItem('pendingInvite');},[user,page,inviteCode]);
 async function action(work:()=>Promise<void>){if(busy)return;setBusy(true);setError('');setSuccess('');try{await work();}catch(e){showError(e);}finally{setBusy(false);}}
 async function createFamily(){await action(async()=>{const {data,error:e}=await supabase().rpc('create_family',{family_name:familyName.trim()});if(e)throw e;setFamilyId(data as string);setFamilyName('');await loadFamilies();router.push('/family');setSuccess(tr('家庭已创建，请添加宝宝。','Family created. Now add your baby.'));});}
 async function joinFamilyByCode(){await action(async()=>{const code=familyCode.replace(/[^a-z0-9]/gi,'').toUpperCase();if(code.length!==10)throw new Error(tr('请输入 10 位家庭编码。','Enter the 10-character family code.'));const {data,error:e}=await supabase().rpc('join_family_by_code',{input_code:code});if(e)throw e;setFamilyId(data as string);setFamilyCode('');await loadFamilies();router.replace('/today');});}
 async function saveBaby(){await action(async()=>{if(!familyId)throw new Error(tr('请先创建家庭。','Create a family first.'));if(!babyForm.name.trim()||!babyForm.birthday)throw new Error(tr('请填写宝宝姓名和出生日期。','Enter the baby’s name and date of birth.'));if(new Date(babyForm.birthday)>new Date())throw new Error(tr('出生日期不能晚于今天。','Date of birth can’t be in the future.'));const weeks=babyForm.gestWeeks.trim();const extra=babyForm.gestDays.trim();let gestation:number|null=null;if(weeks){const w=Number(weeks),d=extra?Number(extra):0;if(!Number.isInteger(w)||w<22||w>44||!Number.isInteger(d)||d<0||d>6)throw new Error(tr('出生孕周请填写 22–44 周，天数 0–6。','Gestational age must be 22–44 weeks and 0–6 days.'));gestation=w*7+d;}else if(extra)throw new Error(tr('请先填写出生孕周的周数。','Enter the weeks of gestational age first.'));const payload={name:babyForm.name.trim(),nickname:babyForm.nickname.trim()||null,birthday:babyForm.birthday,sex:babyForm.sex||null,...(gestation!==null||babyEdit?.gestational_age_days?{gestational_age_days:gestation}:{})};const sb=supabase();const res=babyEdit?await sb.from('babies').update(payload).eq('id',babyEdit.id).eq('family_id',familyId):await sb.from('babies').insert({...payload,family_id:familyId});if(res.error)throw res.error;setBabyForm(emptyBabyForm);setBabyEdit(null);setBabyFormOpen(false);await loadBabies();setSuccess(babyEdit?tr('宝宝资料已更新。','Baby profile updated.'):tr('宝宝已添加。','Baby added.'));});}
 function startFeed(baby:Baby,amount:number){let last:FeedingType='formula';try{last=(localStorage.getItem(`feeding-type:${baby.id}`) as FeedingType)||'formula';}catch{}setEditing(null);setForm({baby_id:baby.id,amount:amount?String(toDisplay(amount)):'',duration:'',mode:!amount&&last==='breast_milk'?'min':'vol',feeding_type:last,fed_at:datetimeLocal(new Date().toISOString(),5),note:''});setError('');}
 function editFeed(item:Feeding){setEditing(item.id);setForm({baby_id:item.baby_id,amount:item.amount_ml===null?'':String(toDisplay(item.amount_ml)),duration:item.duration_min?String(item.duration_min):'',mode:item.feeding_type!=='formula'&&item.amount_ml===null&&(item.duration_min||item.feeding_type==='breast_milk')?'min':'vol',feeding_type:item.feeding_type,fed_at:datetimeLocal(item.fed_at),note:item.note||''});setError('');}
 async function saveFeeding(){if(!form||!user||!familyId)return;await action(async()=>{const rawAmount=form.amount.trim();const typed=rawAmount===''?null:Number(rawAmount);const amount=typed===null?null:fromDisplay(typed);if(typed!==null&&(!Number.isFinite(typed)||typed<=0||amount===null||amount<1||amount>1000))throw new Error(tr(`奶量留空，或输入 ${volumeLabel(1)}–${volumeLabel(1000)} 之间的数。`,`Leave the amount blank, or enter ${volumeLabel(1)}–${volumeLabel(1000)}.`));const rawDuration=form.feeding_type==='formula'?'':form.duration.trim();const duration=rawDuration===''?null:Number(rawDuration);if(duration!==null&&(!Number.isInteger(duration)||duration<1||duration>240))throw new Error(tr('亲喂时长留空，或输入 1–240 之间的整数分钟。','Leave nursing time blank, or enter 1–240 whole minutes.'));if(!validTime(form.fed_at))throw new Error(tr('请输入有效的喂奶时间，不能是未来时间。','Enter a valid feeding time that isn’t in the future.'));if(!activeBabies.some(b=>b.id===form.baby_id))throw new Error(tr('请选择当前家庭的宝宝。','Choose a baby from this family.'));// Only send duration_min when it is used, so saving still works before the duration migration has run.
const payload={baby_id:form.baby_id,family_id:familyId,amount_ml:amount,...(duration!==null||(editing&&feedings.find(f=>f.id===editing)?.duration_min)?{duration_min:duration}:{}),feeding_type:form.feeding_type,fed_at:new Date(form.fed_at).toISOString(),note:form.note.trim()||null};const sb=supabase();const res=editing?await sb.from('feedings').update(payload).eq('id',editing).eq('family_id',familyId).select().single():await sb.from('feedings').insert({...payload,created_by:user.id}).select().single();if(res.error)throw res.error;upsertFeeding(res.data as Feeding);try{localStorage.setItem(`feeding-type:${form.baby_id}`,form.feeding_type);}catch{}setForm(null);setEditing(null);setSuccess(editing?tr('记录已更新。','Record updated.'):amount===null&&duration===null?tr('时间已记录，吃完后可以补充奶量。','Time saved. You can add the amount after the feed.'):tr('记录已保存。','Record saved.'));});}
 async function removeFeeding(){if(!deleteId)return;await action(async()=>{const {error:e}=await supabase().from('feedings').delete().eq('id',deleteId).eq('family_id',familyId);if(e)throw e;dropFeeding(deleteId);setDeleteId(null);setForm(null);setSuccess(tr('记录已删除。','Record deleted.'));});}
 async function removeBaby(baby:Baby){if(!window.confirm(tr(`确定将“${babyName(baby)}”移出宝宝列表？已有的喝奶和体重记录会保留。`,`Remove “${babyName(baby)}” from the baby list? Existing feeding and growth records will be kept.`)))return;await action(async()=>{const {error:e}=await supabase().from('babies').update({is_active:false}).eq('id',baby.id).eq('family_id',familyId);if(e)throw e;await loadBabies();setSuccess(tr('宝宝已移出，历史记录已保留。','Baby removed. Their history has been kept.'));});}
 function chooseAvatar(baby:Baby,file:File){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){showError(new Error(tr('请选择 JPG、PNG 或 WebP 图片。','Choose a JPG, PNG or WebP image.')));return;}if(file.size>5*1024*1024){showError(new Error(tr('头像图片不能超过 5 MB。','The photo must be 5 MB or smaller.')));return;}if(avatarDraft)URL.revokeObjectURL(avatarDraft.url);setAvatarDraft({baby,url:URL.createObjectURL(file)});setError('');}
 function closeAvatarDraft(){if(avatarDraft)URL.revokeObjectURL(avatarDraft.url);setAvatarDraft(null);}
 async function uploadAvatar(baby:Baby,file:File){let saved=false;await action(async()=>{const path=`${familyId}/${baby.id}/${crypto.randomUUID()}.jpg`;const sb=supabase();const {error:uploadError}=await sb.storage.from('baby-avatars').upload(path,file,{contentType:'image/jpeg',cacheControl:'3600'});if(uploadError)throw uploadError;const {error:updateError}=await sb.from('babies').update({avatar_path:path}).eq('id',baby.id).eq('family_id',familyId);if(updateError){await sb.storage.from('baby-avatars').remove([path]);throw updateError;}if(baby.avatar_path)await sb.storage.from('baby-avatars').remove([baby.avatar_path]);await loadBabies();setSuccess(tr(`${babyName(baby)} 的头像已更新。`,`${babyName(baby)}’s photo has been updated.`));saved=true;});return saved;}
 async function setBabySex(baby:Baby,sex:BabySex){await action(async()=>{const {error:e}=await supabase().from('babies').update({sex}).eq('id',baby.id).eq('family_id',familyId);if(e)throw e;await loadBabies();setSuccess(tr(`已保存 ${babyName(baby)} 的资料。`,`Saved ${babyName(baby)}’s profile.`));});}
 async function addGrowthMeasurement(baby:Baby,values:GrowthValues,measuredAt:string,note:string){if(!user)return false;const userId=user.id;let saved=false;await action(async()=>{const parse=(raw:string,min:number,max:number,label:string)=>{const text=raw.trim();if(!text)return null;const value=Number(text);if(!Number.isFinite(value)||value<min||value>max)throw new Error(tr(`${label}请输入 ${min}–${max} 之间的数字。`,`${label} must be a number between ${min} and ${max}.`));return value;};const weight=parse(values.weight,.5,80,tr('体重（kg）','Weight (kg)'));const length=parse(values.length,20,130,tr('身长（cm）','Length (cm)'));const head=parse(values.head,18,60,tr('头围（cm）','Head circumference (cm)'));if(weight===null&&length===null&&head===null)throw new Error(tr('请至少填写体重、身长或头围中的一项。','Enter at least one of weight, length or head circumference.'));if(!measuredAt||measuredAt<baby.birthday||measuredAt>dayKey(new Date()))throw new Error(tr('测量日期应在出生日期至今天之间。','The measurement date must be between birth and today.'));const {data,error:e}=await supabase().from('growth_measurements').insert({baby_id:baby.id,family_id:familyId,recorded_by:userId,weight_kg:weight,...(length!==null?{length_cm:length}:{}),...(head!==null?{head_cm:head}:{}),measured_at:measuredAt,note:note.trim()||null}).select().single();if(e)throw e;upsertGrowth(data as GrowthMeasurement);setSuccess(tr('生长记录已保存。','Growth record saved.'));saved=true;});return saved;}
 async function removeGrowthMeasurement(item:GrowthMeasurement){if(!window.confirm(tr(`删除 ${item.measured_at} 的这条生长记录？`,`Delete the growth record from ${item.measured_at}?`)))return;await action(async()=>{const {error:e}=await supabase().from('growth_measurements').delete().eq('id',item.id).eq('family_id',familyId);if(e)throw e;dropGrowth(item.id);setSuccess(tr('生长记录已删除。','Growth record deleted.'));});}
 async function exportFeedings(){await action(async()=>{const rows=await fetchFeedings(familyId,null);const names=new Map(babies.map(b=>[b.id,babyName(b)]));const csv=toCsv([[tr('时间','Time'),tr('宝宝','Baby'),tr('奶量(ml)','Amount (ml)'),tr('亲喂(分钟)','Nursing (min)'),tr('类型','Type'),tr('备注','Note'),tr('记录人','Logged by')],...[...rows].reverse().map(f=>[localDateTime(f.fed_at),names.get(f.baby_id)??'',f.amount_ml,f.duration_min??null,typeLabels[f.feeding_type],f.note,recorderName(f.created_by)])]);await saveTextFile(tr(`喝奶记录-${dayKey(new Date())}.csv`,`feedings-${dayKey(new Date())}.csv`),csv);setSuccess(tr(`已导出 ${rows.length} 条喝奶记录。`,`Exported ${rows.length} feeding records.`));});}
 async function exportGrowth(){await action(async()=>{const names=new Map(babies.map(b=>[b.id,babyName(b)]));const rows=[...measurements].sort((a,b)=>a.measured_at.localeCompare(b.measured_at));const num=(v:number|null|undefined)=>v===null||v===undefined?null:Number(v);const csv=toCsv([[tr('测量日期','Date measured'),tr('宝宝','Baby'),tr('体重(kg)','Weight (kg)'),tr('身长(cm)','Length (cm)'),tr('头围(cm)','Head (cm)'),tr('备注','Note'),tr('记录人','Logged by')],...rows.map(m=>[m.measured_at,names.get(m.baby_id)??'',num(m.weight_kg),num(m.length_cm),num(m.head_cm),m.note,recorderName(m.recorded_by)])]);await saveTextFile(tr(`生长记录-${dayKey(new Date())}.csv`,`growth-${dayKey(new Date())}.csv`),csv);setSuccess(tr(`已导出 ${rows.length} 条生长记录。`,`Exported ${rows.length} growth records.`));});}
 async function joinFamily(){if(!inviteCode)return;await action(async()=>{const {error:e}=await supabase().rpc('join_family',{invite_token:inviteCode});if(e)throw e;await loadFamilies();router.replace('/today');});}
 async function signOut(){const {error:e}=await supabase().auth.signOut({scope:'local'});if(e){showError(e);return;}router.replace('/auth');}
 function startPull(event:React.TouchEvent){if(refreshing||form||avatarDraft||deleteId||window.scrollY>0)return;const touch=event.touches[0];pullStart.current={x:touch.clientX,y:touch.clientY};pullDistanceRef.current=0;}
 function movePull(event:React.TouchEvent){if(!pullStart.current||refreshing)return;const touch=event.touches[0];const dx=Math.abs(touch.clientX-pullStart.current.x);const dy=touch.clientY-pullStart.current.y;if(dy<=0||dx>dy){pullStart.current=null;pullDistanceRef.current=0;setPullDistance(0);return;}const distance=Math.min(88,dy*.45);pullDistanceRef.current=distance;setPullDistance(distance);event.preventDefault();}
 async function refreshApp(){setRefreshing(true);setPullDistance(52);setError('');setSuccess('');try{await Promise.all([loadFamilies(),loadBabies(),loadMembers(),loadGrowth(),refreshFeedings()]);setNow(Date.now());}catch(e){showError(e);}finally{setRefreshing(false);setPullDistance(0);}}
 function endPull(){const shouldRefresh=pullDistanceRef.current>=56;pullStart.current=null;pullDistanceRef.current=0;if(shouldRefresh&&!refreshing)void refreshApp();else setPullDistance(0);}
 function cancelPull(){pullStart.current=null;pullDistanceRef.current=0;setPullDistance(0);}
 const editingItem=editing?feedings.find(f=>f.id===editing):undefined;
 if(!ready)return <main className="mx-auto flex min-h-screen max-w-lg items-center justify-center text-(--muted)">{tr('正在加载…','Loading…')}</main>;
 if(page==='auth')return <AuthView onError={showError} user={user} />;
 if(page==='reset-password')return <ResetView onError={showError}/>;
 if(!user)return <main className="p-8">{tr('正在打开登录页面…','Opening sign-in…')}</main>;
 if(page==='join')return <main className="mx-auto flex min-h-screen max-w-lg flex-col justify-center p-6"><div className={card}><div className="mb-4 text-3xl">✳</div><h1 className="text-3xl font-semibold">{tr('一起照顾宝宝','Care for your baby together')}</h1><p className="mt-3 text-(--muted)">{tr('加入家庭后，你可以查看和记录这个家庭的喝奶数据。','After joining, you can view and log this family’s feeding data.')}</p>{error&&<Alert text={error}/>}<button className={`${primary} mt-7`} disabled={busy} onClick={joinFamily}>{busy?tr('正在加入…','Joining…'):tr('加入家庭','Join family')}</button><button className="mt-4 w-full p-3 text-(--brand)" onClick={()=>router.push('/today')}>{tr('返回','Back')}</button></div></main>;
 if(!familiesLoaded||(familyId&&loadedFamilyId!==familyId))return <main className="mx-auto flex min-h-screen max-w-lg items-center justify-center text-(--muted)">{tr('正在加载…','Loading…')}</main>;
 if(page==='onboarding'&&familyId)return <main className="mx-auto flex min-h-screen max-w-lg items-center justify-center text-(--muted)">{tr('正在进入家庭…','Opening family…')}</main>;
 if(!familyId)return <main className="mx-auto min-h-screen max-w-lg p-6 pb-16"><div className="pt-12"><span className="text-3xl">✳</span><p className="mt-7 text-sm font-semibold tracking-[.2em] text-(--brand)">{tr('欢迎来到奶记','Welcome')}</p><h1 className="mt-3 text-4xl font-semibold leading-tight">{tr('绑定你的家庭，','Link your family,')}<br/>{tr('一起记录每一顿奶。','and log every feed together.')}</h1><p className="mt-4 text-(--muted)">{tr('每个账号绑定一个家庭。你可以创建新家庭，或使用家人分享的唯一编码加入。','Each account belongs to one family. Create a new family, or join one with the code a family member shares.')}</p></div>{error&&<Alert text={error}/>} {success&&<Alert text={success} good/>}<section className={`${card} mt-10`}><p className="mb-4 text-sm font-semibold text-(--brand)">{tr('创建新家庭','Create a family')}</p><label className="mb-2 block font-medium" htmlFor="family-name">{tr('家庭名称','Family name')}</label><input id="family-name" className={input} placeholder={tr('例如 Di Family','e.g. Di Family')} value={familyName} onChange={e=>setFamilyName(e.target.value)} maxLength={100}/><button className={`${primary} mt-4`} disabled={busy||!familyName.trim()} onClick={createFamily}>{busy?tr('处理中…','Working…'):tr('创建并绑定家庭','Create family')}</button></section><div className="my-5 flex items-center gap-3 text-sm text-(--soft)"><span className="h-px flex-1 bg-(--line)"/><span>{tr('或者','or')}</span><span className="h-px flex-1 bg-(--line)"/></div><section className={card}><p className="mb-4 text-sm font-semibold text-(--brand)">{tr('加入已有家庭','Join a family')}</p><label className="mb-2 block font-medium" htmlFor="family-code">{tr('家庭编码','Family code')}</label><input id="family-code" className={`${input} uppercase tracking-[.18em]`} placeholder={tr('10 位家庭编码','10-character family code')} value={familyCode} onChange={e=>setFamilyCode(e.target.value.replace(/[^a-z0-9]/gi,'').toUpperCase().slice(0,10))} maxLength={10} autoCapitalize="characters" autoComplete="off"/><button className={`${primary} mt-4`} disabled={busy||familyCode.length!==10} onClick={joinFamilyByCode}>{busy?tr('正在绑定…','Joining…'):tr('绑定已有家庭','Join family')}</button></section></main>;
 const nav:[Page,string,typeof House][]=[['today',tr('今天','Today'),LayoutDashboard],['history',tr('记录','Records'),CalendarDays],['growth',tr('生长','Growth'),Scale],['family',tr('家庭','Family'),House]];
 return <><div role="status" aria-live="polite" className="fixed left-1/2 top-[max(12px,env(safe-area-inset-top))] z-0 flex -translate-x-1/2 items-center gap-2 text-sm font-semibold text-(--brand)">{refreshing?<><LoaderCircle className="animate-spin" size={18}/>{tr('正在刷新','Refreshing')}</>:pullDistance>0?<><ArrowDown className={pullDistance>=56?'rotate-180 transition-transform':'transition-transform'} size={18}/>{pullDistance>=56?tr('松开刷新','Release to refresh'):tr('下拉刷新','Pull to refresh')}</>:null}</div><div className="relative z-[1] mx-auto min-h-screen max-w-lg border-x border-(--rim)/50 bg-(--surface)/10 shadow-[0_0_70px_rgba(15,50,38,.06)]"><div className="min-h-screen pb-32" style={{transform:`translateY(${pullDistance}px)`,transition:pullStart.current===null?'transform 180ms ease':'none'}} onTouchStart={startPull} onTouchMove={movePull} onTouchEnd={endPull} onTouchCancel={cancelPull}><main className="space-y-6 px-5 pt-[max(24px,env(safe-area-inset-top))]">{error&&<Alert text={error}/>} {success&&<Alert text={success} good/>}{loading&&!refreshing&&<p className="text-sm text-(--muted)">{tr('正在同步…','Syncing…')}</p>}
 {page==='today'&&<TodayView babies={activeBabies} feedings={feedings} avatarUrls={avatarUrls} now={now} recorderName={recorderName} onStartFeed={startFeed} onEditFeed={editFeed} onAddBaby={()=>router.push('/family')}/>}
 {(page==='history'||page==='trends')&&<><PageIntro title={tr('喂养记录','Feeding records')}/><div className="flex rounded-[18px] border border-(--rim)/80 bg-(--chip)/80 p-1.5 shadow-inner" role="tablist" aria-label={tr('历史或趋势','History or trends')}>{([['history',tr('历史','History'),CalendarDays],['trends',tr('趋势','Trends'),ChartNoAxesCombined]] as const).map(([key,label,Icon])=><button key={key} type="button" role="tab" aria-selected={page===key} className={`flex min-h-11 flex-1 items-center justify-center gap-2 rounded-[14px] font-semibold transition ${page===key?'bg-(--paper) text-(--brand) shadow-[0_3px_12px_rgba(30,67,52,.09)]':'text-(--muted)'}`} onClick={()=>{try{localStorage.setItem('records-tab',key);}catch{}router.replace(`/${key}`);}}><Icon size={18}/>{label}</button>)}</div></>}
 {page==='history'&&<><HistoryCalendar babies={babies} feedings={feedings} onSelect={editFeed} recorderName={recorderName} onMonthChange={ensureFeedingsSince} loadingOlder={loadingOlder}/></>}
 {page==='trends'&&<><div className="flex rounded-[18px] border border-(--rim)/80 bg-(--chip)/80 p-1.5 shadow-inner" role="group" aria-label={tr('趋势天数','Trend range')}>{([7,30] as const).map(n=><button key={n} className={`min-h-11 flex-1 rounded-[14px] font-semibold transition ${range===n?'bg-(--paper) text-(--brand) shadow-[0_3px_12px_rgba(30,67,52,.09)]':'text-(--muted)'}`} onClick={()=>setRange(n)}>{tr(`近 ${n} 天`,`Last ${n} days`)}</button>)}</div><TrendView babies={activeBabies} feedings={feedings} days={range}/></>}
 {page==='growth'&&<><PageIntro title={tr('生长曲线','Growth')}/><GrowthView babies={activeBabies} measurements={measurements} busy={busy} onAdd={addGrowthMeasurement} onDelete={removeGrowthMeasurement} onSetSex={setBabySex}/></>}
 {page==='family'&&<PageIntro title={tr('家庭','Family')}/>}
 {page==='family'&&<><section className={card}><div className="flex items-start justify-between"><div><p className="text-sm text-(--muted)">{tr('当前家庭','Current family')}</p><h2 className="mt-1 text-2xl font-semibold">{family?.name}</h2></div><House className="text-(--brand)"/></div><details className="group mt-4 rounded-2xl bg-(--surface-2) px-4 py-1.5"><summary className="flex min-h-11 cursor-pointer list-none items-center justify-between gap-3 [&::-webkit-details-marker]:hidden text-sm text-(--muted)"><span>{tr('唯一家庭编码','Family code')}</span><ChevronDown size={18} className="shrink-0 text-(--soft) transition-transform group-open:rotate-180"/></summary><div className="pb-2.5"><div className="flex items-center justify-between gap-3"><strong className="text-xl tracking-[.16em] text-(--ink)">{family?.family_code}</strong><button className="min-h-11 shrink-0 font-semibold text-(--brand)" onClick={async()=>{if(!family?.family_code)return;try{await navigator.clipboard.writeText(family.family_code);setSuccess(tr('家庭编码已复制。','Family code copied.'));}catch{setError(tr('复制失败，请手动复制家庭编码。','Couldn’t copy. Please copy the family code manually.'));}}}>{tr('复制','Copy')}</button></div><p className="mt-2 text-xs leading-relaxed text-(--soft)">{tr('家人注册后输入此编码，即可绑定并共享家庭数据。','Family members enter this code after signing up to share this family’s data.')}</p></div></details><div className="mt-5 border-t border-(--line) pt-4"><div className="mb-1 flex items-center justify-between"><h3 className="text-lg font-semibold">{tr('宝宝','Baby')} <span className="text-sm font-normal text-(--muted)">{activeBabies.length}</span></h3></div>{activeBabies.length===0&&<p className="my-2 text-sm text-(--muted)">{tr('添加宝宝后即可开始记录。','Add a baby to start logging.')}</p>}{activeBabies.map(b=><div key={b.id} className="flex items-center gap-3 border-b border-(--line) py-3 last:border-0"><BabyAvatar baby={b} url={avatarUrls[b.id]} small/><div className="min-w-0 flex-1"><p className="font-semibold">{babyName(b)}</p><p className="text-xs text-(--soft)">{b.name!==babyName(b)?`${b.name} · `:''}{tr('生日','Born')} {b.birthday}{b.sex?` · ${b.sex==='female'?tr('女孩','Girl'):tr('男孩','Boy')}`:''}{b.gestational_age_days?tr(` · 孕 ${gestationLabel(b.gestational_age_days)}`,` · born at ${gestationLabel(b.gestational_age_days)}`):''}</p></div><label className="flex h-11 w-11 shrink-0 cursor-pointer items-center justify-center rounded-full text-(--brand)" aria-label={tr(`上传或更换 ${babyName(b)} 的头像`,`Upload or change ${babyName(b)}’s photo`)} title={tr('更换头像','Change photo')}><Camera size={19}/><input className="sr-only" type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={e=>{const file=e.target.files?.[0];e.target.value='';if(file)chooseAvatar(b,file);}}/></label><button className="min-h-11 px-1 text-sm text-(--brand)" onClick={()=>{setBabyEdit(b);setBabyForm({name:b.name,nickname:b.nickname||'',birthday:b.birthday,sex:b.sex||'',gestWeeks:b.gestational_age_days?String(Math.floor(b.gestational_age_days/7)):'',gestDays:b.gestational_age_days?String(b.gestational_age_days%7):''});setBabyFormOpen(true);}}>{tr('编辑','Edit')}</button><button className="min-h-11 px-2 text-sm text-(--danger)" onClick={()=>removeBaby(b)}>{tr('移出','Remove')}</button></div>)}<button type="button" className={`${primary} mt-3`} aria-expanded={babyFormOpen} aria-controls="baby-form" onClick={()=>{if(babyFormOpen){setBabyFormOpen(false);setBabyEdit(null);setBabyForm(emptyBabyForm);}else setBabyFormOpen(true);}}><Plus size={19}/>{babyFormOpen?(babyEdit?tr('收起编辑宝宝','Close editor'):tr('收起添加宝宝','Close')):tr('添加宝宝','Add baby')}</button>{babyFormOpen&&<div id="baby-form" className="mt-3 rounded-2xl border border-(--line) bg-(--surface-2) p-4"><h3 className="mb-4 font-semibold">{babyEdit?tr('编辑宝宝','Edit baby'):tr('添加宝宝','Add baby')}</h3><div className="space-y-3"><label className="block text-sm">{tr('姓名','Name')}<input className={`${input} mt-1`} value={babyForm.name} maxLength={100} onChange={e=>setBabyForm({...babyForm,name:e.target.value})} placeholder={tr('宝宝姓名','Baby’s name')}/></label><label className="block text-sm">{tr('昵称（可选）','Nickname (optional)')}<input className={`${input} mt-1`} value={babyForm.nickname} maxLength={100} onChange={e=>setBabyForm({...babyForm,nickname:e.target.value})} placeholder={tr('常用昵称','Nickname')}/></label><label className="block text-sm">{tr('出生日期','Date of birth')}<input className={`${input} mt-1`} type="date" max={dayKey(new Date())} value={babyForm.birthday} onChange={e=>setBabyForm({...babyForm,birthday:e.target.value})}/></label><fieldset><legend className="text-sm">{tr('出生孕周（早产宝宝填写，足月可留空）','Gestational age at birth (for premature babies; leave blank if full term)')}</legend><div className="mt-1 grid grid-cols-2 gap-2"><label className="flex items-center gap-2 text-sm"><input className={input} type="number" inputMode="numeric" min="22" max="44" placeholder={tr('例如 34','e.g. 34')} aria-label={tr('出生孕周的周数','Gestational weeks at birth')} value={babyForm.gestWeeks} onChange={e=>setBabyForm({...babyForm,gestWeeks:e.target.value})}/>{tr('周','wk')}</label><label className="flex items-center gap-2 text-sm"><input className={input} type="number" inputMode="numeric" min="0" max="6" placeholder="0–6" aria-label={tr('出生孕周的天数','Extra days')} value={babyForm.gestDays} onChange={e=>setBabyForm({...babyForm,gestDays:e.target.value})}/>{tr('天','d')}</label></div><p className="mt-1 text-xs text-(--soft)">{tr('不满 37 周时，生长曲线按矫正月龄计算。','Below 37 weeks, growth charts use corrected age.')}</p></fieldset><fieldset><legend className="mb-2 text-sm">{tr('性别（用于生长曲线）','Sex (used for growth charts)')}</legend><div className="grid grid-cols-3 gap-2">{([['',tr('暂不设置','Not set')],['female',tr('女孩','Girl')],['male',tr('男孩','Boy')]] as const).map(([value,label])=><button key={value||'none'} type="button" aria-pressed={babyForm.sex===value} className={`min-h-12 rounded-2xl border text-sm font-semibold ${babyForm.sex===value?'border-(--brand) bg-(--brand-pale) text-(--brand)':'border-(--line) bg-(--surface) text-(--muted)'}`} onClick={()=>setBabyForm({...babyForm,sex:value})}>{label}</button>)}</div></fieldset></div><button className={`${primary} mt-4`} disabled={busy||!babyForm.name.trim()||!babyForm.birthday} onClick={saveBaby}>{busy?tr('保存中…','Saving…'):babyEdit?tr('保存修改','Save changes'):tr('添加宝宝','Add baby')}</button><button className="mt-2 w-full p-3 text-(--muted)" onClick={()=>{setBabyFormOpen(false);setBabyEdit(null);setBabyForm(emptyBabyForm);}}>{tr('取消','Cancel')}</button></div>}</div><div className="mt-5 border-t border-(--line) pt-4"><h3 className="text-lg font-semibold">{tr('家庭成员','Family members')}</h3><div className="mt-3 space-y-3">{members.map(m=><div key={m.id} className="flex items-center justify-between border-b border-(--line) pb-3 last:border-0"><span>{m.display_name|| (m.user_id===user.id?tr('我','Me'):tr(`成员 ${m.user_id.slice(0,6)}`,`Member ${m.user_id.slice(0,6)}`))}</span><span className="text-sm text-(--muted)">{m.role==='owner'?tr('创建者','Owner'):tr('成员','Member')}</span></div>)}</div></div></section><details className={`${card} group`}><summary className="flex min-h-11 cursor-pointer list-none items-center justify-between gap-3 [&::-webkit-details-marker]:hidden"><h2 className="text-xl font-semibold">{tr('数据导出','Export data')}</h2><ChevronDown size={18} className="shrink-0 text-(--soft) transition-transform group-open:rotate-180"/></summary><p className="mt-1 text-sm leading-relaxed text-(--muted)">{tr('导出为 CSV，可用 Excel 或 Numbers 打开。换手机前建议备份一次。','Export as CSV to open in Excel or Numbers. A good backup before switching phones.')}</p><div className="mt-4 grid grid-cols-2 gap-2"><button className="flex min-h-12 items-center justify-center gap-2 rounded-2xl border border-(--line-strong) bg-(--surface)/75 font-semibold text-(--brand)" disabled={busy} onClick={exportFeedings}><Download size={18}/>{tr('喝奶记录','Feedings')}</button><button className="flex min-h-12 items-center justify-center gap-2 rounded-2xl border border-(--line-strong) bg-(--surface)/75 font-semibold text-(--brand)" disabled={busy} onClick={exportGrowth}><Download size={18}/>{tr('生长记录','Growth records')}</button></div></details><section className={card}><h2 className="mb-3 text-xl font-semibold">{tr('账户','Account')}</h2><button className="flex min-h-12 items-center gap-2 text-(--danger)" onClick={signOut}><LogOut size={18}/>{tr('退出登录','Sign out')}</button></section><button type="button" className={`${card} flex min-h-16 w-full items-center gap-3 text-left`} onClick={()=>setSettingsOpen(true)}><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-(--brand-pale) text-(--brand)"><Settings size={20}/></span><span className="flex-1"><span className="block font-semibold">{tr('设置','Settings')}</span><span className="block text-sm text-(--muted)">{tr('语言','Language')} · {languages.find(l=>l.value===lang)?.label} · {unit}</span></span><ChevronRight size={18} className="text-(--faint)"/></button></>}
 </main></div><nav className="safe-bottom fixed bottom-[max(10px,env(safe-area-inset-bottom))] left-1/2 z-20 flex w-[calc(100%_-_24px)] max-w-[488px] -translate-x-1/2 rounded-[25px] border border-(--rim)/90 bg-(--paper)/92 p-1.5 shadow-[0_12px_40px_rgba(19,50,39,.18)] backdrop-blur-2xl" aria-label={tr('主导航','Main navigation')}>{nav.map(([key,label,Icon])=>{const on=page===key||(key==='history'&&page==='trends');return <button key={key} aria-current={on?'page':undefined} className={`flex min-h-[58px] flex-1 flex-col items-center justify-center gap-0.5 rounded-[19px] text-[11px] transition ${on?'bg-(--brand-pale) font-bold text-(--brand)':'text-(--soft) active:bg-(--surface-2)'}`} onClick={()=>router.push(`/${key==='history'?recordsTab():key}`)}><Icon size={21} strokeWidth={on?2.5:1.8}/>{label}</button>;})}</nav>
 {avatarDraft&&<AvatarCropper src={avatarDraft.url} name={babyName(avatarDraft.baby)} busy={busy} uploadError={error} onCancel={closeAvatarDraft} onConfirm={async file=>{if(await uploadAvatar(avatarDraft.baby,file))closeAvatarDraft();}}/>}
 {form&&<div className="fixed inset-0 z-30 flex items-end justify-center bg-[#10231b]/40" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)setForm(null);}}><div role="dialog" aria-modal="true" aria-label={editing?tr('编辑喝奶记录','Edit feeding'):tr('记录喝奶','Log feeding')} className="safe-bottom max-h-[94dvh] w-full max-w-lg overscroll-contain overflow-y-auto rounded-t-[32px] bg-(--surface-2) p-5 shadow-2xl"><div className="mx-auto mb-5 h-1.5 w-12 rounded-full bg-(--line)"/><div className="flex items-center justify-between"><div><p className="text-sm text-(--brand)">{editing?(editingItem?tr(`编辑记录 · ${recorderName(editingItem.created_by)}记录`,`Edit · logged by ${recorderName(editingItem.created_by)}`):tr('编辑记录','Edit record')):tr('快速记录','Quick log')}</p><h2 className="text-2xl font-semibold">{babyName(activeBabies.find(b=>b.id===form.baby_id)||babies.find(b=>b.id===form.baby_id)||activeBabies[0])}</h2></div><button className="flex h-11 w-11 items-center justify-center rounded-full bg-(--chip)" aria-label={tr('关闭','Close')} onClick={()=>setForm(null)} disabled={busy}><X size={20}/></button></div>{error&&<Alert text={error}/>}<div className="mt-6 space-y-5"><div className="block text-sm font-medium"><div className="flex items-center justify-between gap-3"><span>{form.mode==='min'?tr('亲喂时长 · 分钟（可稍后填写）','Nursing time · min (can add later)'):tr(`奶量 · ${unit}（可稍后填写）`,`Amount · ${unit} (can add later)`)}</span>{form.feeding_type!=='formula'&&<div className="flex shrink-0 rounded-xl bg-(--chip) p-1" role="group" aria-label={tr('输入方式','Input type')}>{(['min','vol'] as const).map(m=><button key={m} type="button" aria-pressed={form.mode===m} className={`min-h-8 rounded-lg px-3 text-xs font-semibold ${form.mode===m?'bg-(--paper) text-(--brand) shadow-sm':'text-(--muted)'}`} onClick={()=>setForm({...form,mode:m})}>{m==='min'?tr('分钟','min'):unit}</button>)}</div>}</div>{form.mode==='min'&&form.feeding_type!=='formula'?<input key="min" className={`${input} mt-2 font-semibold`} style={{fontSize:'24px'}} type="number" aria-label={tr('亲喂时长（分钟）','Nursing time (minutes)')} placeholder={tr('可以先留空','Can be left blank')} inputMode="numeric" enterKeyHint="done" min="1" max="240" step="1" value={form.duration} onChange={e=>setForm({...form,duration:e.target.value})}/>:<input key="vol" className={`${input} mt-2 font-semibold`} style={{fontSize:'24px'}} type="number" aria-label={tr(`奶量（${unit}）`,`Amount (${unit})`)} placeholder={tr('可以先留空','Can be left blank')} inputMode={unit==='oz'?'decimal':'numeric'} enterKeyHint="done" min={unit==='oz'?'0.1':'1'} step={unit==='oz'?'0.1':'1'} value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/>}</div><fieldset><legend className="mb-2 text-sm font-medium">{tr('奶类型','Milk type')}</legend><div className="grid grid-cols-3 gap-2">{(Object.keys(typeLabels) as FeedingType[]).map(t=><button key={t} type="button" aria-pressed={form.feeding_type===t} className={`min-h-13 rounded-2xl border text-sm font-semibold ${form.feeding_type===t?'border-(--brand) bg-(--brand-pale) text-(--brand)':'border-(--line) bg-(--surface) text-(--muted)'}`} onClick={()=>setForm({...form,feeding_type:t,mode:t==='formula'?'vol':t==='breast_milk'&&!form.amount.trim()?'min':form.mode})}>{typeLabels[t]}</button>)}</div></fieldset><div className="block text-sm font-medium">{tr('时间','Time')}<DateTimeWheel value={form.fed_at} onChange={value=>setForm(current=>current?{...current,fed_at:value}:current)}/></div><label className="block text-sm font-medium">{tr('备注（可选）','Note (optional)')}<textarea className={`${input} mt-2 min-h-20`} maxLength={1000} value={form.note} onChange={e=>setForm({...form,note:e.target.value})}/></label></div><button className={`${primary} mt-6`} disabled={busy} onClick={saveFeeding}>{busy?tr('保存中…','Saving…'):tr('保存记录','Save')}</button>{editing&&<button className="mt-3 min-h-12 w-full text-(--danger)" disabled={busy} onClick={()=>setDeleteId(editing)}>{tr('删除这条记录','Delete this record')}</button>}</div></div>}
 {settingsOpen&&<div className="fixed inset-0 z-30 flex items-end justify-center bg-[#10231b]/40" onMouseDown={e=>{if(e.target===e.currentTarget)setSettingsOpen(false);}}><div role="dialog" aria-modal="true" aria-label={tr('设置','Settings')} className="ui-sheet safe-bottom max-h-[94dvh] w-full max-w-lg overflow-y-auto p-5"><div className="mx-auto mb-5 h-1.5 w-12 rounded-full bg-(--line)"/><div className="flex items-center justify-between"><h2 className="text-2xl font-semibold">{tr('设置','Settings')}</h2><button className="flex h-11 w-11 items-center justify-center rounded-full bg-(--chip)" aria-label={tr('关闭','Close')} onClick={()=>setSettingsOpen(false)}><X size={20}/></button></div><fieldset className="mt-6"><legend className="mb-3 flex items-center gap-2 text-sm font-semibold text-(--muted)"><Languages size={16}/>{tr('语言','Language')}</legend><div className="overflow-hidden rounded-2xl border border-(--line) bg-(--surface)">{languages.map(option=><button key={option.value} type="button" role="radio" aria-checked={lang===option.value} className="flex min-h-14 w-full items-center justify-between border-b border-(--line) px-4 text-left font-medium last:border-0" onClick={()=>setLang(option.value)}><span>{option.label}</span>{lang===option.value&&<Check size={20} className="text-(--brand)"/>}</button>)}</div><p className="mt-2 text-xs text-(--soft)">{tr('只对这台设备生效，家人可以各自选择语言。','Applies to this device only. Each family member can choose their own.')}</p></fieldset><fieldset className="mt-6"><legend className="mb-3 flex items-center gap-2 text-sm font-semibold text-(--muted)"><Milk size={16}/>{tr('奶量单位','Volume unit')}</legend><div className="overflow-hidden rounded-2xl border border-(--line) bg-(--surface)">{volumeUnits.map(option=><button key={option.value} type="button" role="radio" aria-checked={unit===option.value} className="flex min-h-14 w-full items-center justify-between border-b border-(--line) px-4 text-left font-medium last:border-0" onClick={()=>setUnit(option.value)}><span>{option.value==='ml'?tr('毫升 (ml)','Millilitres (ml)'):tr('盎司 (oz)','Ounces (oz)')}</span>{unit===option.value&&<Check size={20} className="text-(--brand)"/>}</button>)}</div><p className="mt-2 text-xs text-(--soft)">{tr('只影响这台设备的显示和输入，记录统一按 ml 保存，1 oz ≈ 29.6 ml。','Changes display and input on this device only. Records are stored in ml; 1 oz ≈ 29.6 ml.')}</p></fieldset></div></div>}
 {deleteId&&<div className="fixed inset-0 z-40 flex items-center justify-center bg-[#10231b]/50 p-6"><div role="alertdialog" aria-modal="true" aria-label={tr('确认删除','Confirm delete')} className={`${card} w-full max-w-sm`}><h2 className="text-xl font-semibold">{tr('确认删除这条记录？','Delete this record?')}</h2><p className="mt-2 text-sm text-(--muted)">{tr('删除后无法恢复。','This can’t be undone.')}</p>{error&&<Alert text={error}/>}<div className="mt-6 grid grid-cols-2 gap-3"><button className="min-h-12 rounded-xl border border-(--line)" disabled={busy} onClick={()=>setDeleteId(null)}>{tr('取消','Cancel')}</button><button className="min-h-12 rounded-xl bg-(--danger) font-semibold text-white" disabled={busy} onClick={removeFeeding}>{busy?tr('删除中…','Deleting…'):tr('删除','Delete')}</button></div></div></div>}
 </div></>;
}
// The Records tab reopens whichever of History / Trends was used last.
function recordsTab(){try{return localStorage.getItem('records-tab')==='trends'?'trends':'history';}catch{return 'history';}}
function PageIntro({title}:{title:string}){return <header className="px-1"><h1 className="page-title">{title}</h1></header>;}
function Alert({text,good=false}:{text:string;good?:boolean}){return <p role={good?'status':'alert'} className={`mt-4 rounded-2xl p-4 text-sm ${good?'bg-(--brand-pale) text-(--brand)':'bg-(--danger-pale) text-(--danger)'}`}>{text}</p>;}
function TrendView({babies,feedings,days}:{babies:Baby[];feedings:Feeding[];days:7|30}){const unit=useUnit();const palette=chartPalette(useDarkMode());const colors=palette.series;const rows=Array.from({length:days},(_,i)=>{const d=localDay();d.setDate(d.getDate()-(days-1-i));const key=dayKey(d);const row:Record<string,string|number>={date:key,label:`${d.getMonth()+1}/${d.getDate()}`};babies.forEach(b=>row[b.id]=0);feedings.forEach(f=>{if(dayKey(new Date(f.fed_at))===key&&row[f.baby_id]!==undefined)row[f.baby_id]=Number(row[f.baby_id])+(f.amount_ml??0);});babies.forEach(b=>row[b.id]=toDisplay(Number(row[b.id])));return row;});const since=localDay();since.setDate(since.getDate()-(days-1));return <><section className={card}><h2 className="text-xl font-semibold">{tr('每日总奶量','Daily total')}</h2><p className="mt-1 text-sm text-(--muted)">{tr(`单位 ${unit} · 按本地日期统计`,`${unit} · by local date`)}</p>{babies.length?<div className="mt-5 h-72 w-full" role="img" aria-label={tr(`${days} 天各宝宝每日奶量趋势`,`Daily intake per baby over ${days} days`)}><ResponsiveContainer width="100%" height="100%"><AreaChart data={rows} margin={{top:10,right:5,left:-25,bottom:0}}><CartesianGrid vertical={false} stroke={palette.grid}/><XAxis dataKey="label" tick={{fontSize:11,fill:palette.tick}} tickLine={false} axisLine={false} minTickGap={15}/><YAxis tick={{fontSize:11,fill:palette.tick}} tickLine={false} axisLine={false}/><Tooltip contentStyle={palette.tooltip} formatter={(value,name)=>[`${value} ${unit}`,babies.find(b=>b.id===name)?.nickname||babies.find(b=>b.id===name)?.name||name]}/><Legend formatter={value=>babies.find(b=>b.id===value)?.nickname||babies.find(b=>b.id===value)?.name||value}/>{babies.map((b,i)=><Area key={b.id} type="monotone" dataKey={b.id} name={b.id} stroke={colors[i%colors.length]} fill={colors[i%colors.length]} fillOpacity={.08} strokeWidth={2.5} dot={days===7} isAnimationActive={false}/>)}</AreaChart></ResponsiveContainer></div>:<p className="mt-6 text-(--muted)">{tr('添加宝宝后即可查看趋势。','Add a baby to see trends.')}</p>}</section>{babies.map((b,i)=>{const items=feedings.filter(f=>f.baby_id===b.id&&new Date(f.fed_at)>=since);const completed=items.filter((item):item is Feeding&{amount_ml:number}=>item.amount_ml!==null);const total=completed.reduce((s,f)=>s+f.amount_ml,0);return <section className={card} key={b.id}><div className="flex items-center gap-2"><span className="h-3 w-3 rounded-full" style={{background:colors[i%colors.length]}}/><h3 className="text-lg font-semibold">{babyName(b)}</h3></div><div className="mt-5 grid grid-cols-3 gap-2 text-center"><div><strong className="text-xl">{toDisplay(total/days)}</strong><p className="mt-1 text-xs text-(--muted)">{tr(`${unit} / 天`,`${unit} / day`)}</p></div><div><strong className="text-xl">{(items.length/days).toFixed(1)}</strong><p className="mt-1 text-xs text-(--muted)">{tr('次 / 天','feeds / day')}</p></div><div><strong className="text-xl">{completed.length?toDisplay(total/completed.length):0}</strong><p className="mt-1 text-xs text-(--muted)">{tr(`${unit} / 次`,`${unit} / feed`)}</p></div></div></section>;})}<p className="px-1 text-xs leading-relaxed text-(--soft)">{tr('仅展示记录的描述性统计，不用于医疗判断。','Descriptive statistics of your records only. Not for medical decisions.')}</p></>;}
function AuthView({onError,user}:{onError:(e:unknown)=>void;user:User|null}){const router=useRouter();const [mode,setMode]=useState<'login'|'signup'|'forgot'>('login');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [name,setName]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();if(busy)return;setBusy(true);setError('');setMessage('');try{const sb=supabase();if(mode==='forgot'){const {error:err}=await sb.auth.resetPasswordForEmail(email,{redirectTo:`${window.location.origin}/reset-password`});if(err)throw err;setMessage(tr('如果该邮箱已注册，重置邮件已发送。','If this email is registered, a reset email has been sent.'));}else if(mode==='signup'){const {data,error:err}=await sb.auth.signUp({email,password,options:{emailRedirectTo:`${window.location.origin}/auth`,data:{display_name:name.trim()}}});if(err)throw err;if(data.session){await sb.from('profiles').upsert({id:data.user!.id,display_name:name.trim()});router.replace('/onboarding');}else setMessage(tr('注册成功。请查收验证邮件，然后登录。','Account created. Check your email to verify it, then sign in.'));}else{const {data,error:err}=await sb.auth.signInWithPassword({email,password});if(err)throw err;const pending=localStorage.getItem('pendingInvite');router.replace(pending?`/join/${pending}`:'/today');if(data.user){await sb.from('profiles').upsert({id:data.user.id,display_name:data.user.user_metadata?.display_name||''});}}}catch(e){setError(getError(e));onError(e);}finally{setBusy(false);}}return <main className="mx-auto flex min-h-screen max-w-lg flex-col justify-center p-6"><div className="mb-10"><div className="flex h-16 w-16 items-center justify-center rounded-[22px] bg-(--brand-solid) text-3xl text-white">✳</div><p className="mt-8 text-sm font-semibold tracking-[.2em] text-(--brand)">{tr('奶记 · BABY FEEDING','BABY FEEDING')}</p><h1 className="mt-3 text-4xl font-semibold leading-tight">{tr('每一顿奶，','Every feed,')}<br/>{tr('都记得轻松一点。','logged with ease.')}</h1><p className="mt-4 text-(--muted)">{tr('为忙碌的家庭准备的简单喝奶记录。','Simple feeding log for busy families.')}</p></div><form className={card} onSubmit={submit}><h2 className="mb-5 text-xl font-semibold">{mode==='signup'?tr('创建账号','Create account'):mode==='forgot'?tr('重置密码','Reset password'):tr('欢迎回来','Welcome back')}</h2>{message&&<Alert text={message} good/>}{error&&<Alert text={error}/>}<div className="space-y-4">{mode==='signup'&&<label className="block text-sm font-medium">{tr('称呼','Your name')}<input className={`${input} mt-2`} value={name} onChange={e=>setName(e.target.value)} maxLength={100} required autoComplete="name"/></label>}<label className="block text-sm font-medium">{tr('邮箱','Email')}<input className={`${input} mt-2`} type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></label>{mode!=='forgot'&&<label className="block text-sm font-medium">{tr('密码','Password')}<input className={`${input} mt-2`} type="password" minLength={6} value={password} onChange={e=>setPassword(e.target.value)} required autoComplete={mode==='signup'?'new-password':'current-password'}/></label>}</div><button className={`${primary} mt-6`} disabled={busy}>{busy?tr('请稍候…','Please wait…'):mode==='signup'?tr('注册','Sign up'):mode==='forgot'?tr('发送重置邮件','Send reset email'):tr('登录','Sign in')}</button><div className="mt-4 flex items-center justify-center gap-4 text-sm text-(--brand)"><button type="button" className="min-h-11" onClick={()=>{setMode(mode==='signup'?'login':'signup');setError('');setMessage('');}}>{mode==='signup'?tr('已有账号？登录','Have an account? Sign in'):tr('创建账号','Create account')}</button><button type="button" className="min-h-11" onClick={()=>{setMode(mode==='forgot'?'login':'forgot');setError('');setMessage('');}}>{mode==='forgot'?tr('返回登录','Back to sign in'):tr('忘记密码','Forgot password')}</button></div></form>{user&&<button className="mt-5 text-(--brand)" onClick={()=>router.push('/today')}>{tr('进入应用 →','Open app →')}</button>}</main>;}
function ResetView({onError}:{onError:(e:unknown)=>void}){const router=useRouter();const [password,setPassword]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const {error:err}=await supabase().auth.updateUser({password});if(err)throw err;router.replace('/today');}catch(e){setError(getError(e));onError(e);}finally{setBusy(false);}}return <main className="mx-auto flex min-h-screen max-w-lg items-center p-6"><form className={`${card} w-full`} onSubmit={submit}><h1 className="text-2xl font-semibold">{tr('设置新密码','Set a new password')}</h1>{error&&<Alert text={error}/>}<label className="mt-6 block text-sm">{tr('新密码','New password')}<input className={`${input} mt-2`} type="password" minLength={6} required value={password} onChange={e=>setPassword(e.target.value)}/></label><button className={`${primary} mt-5`} disabled={busy}>{tr('保存新密码','Save password')}</button></form></main>;}
